-- =====================================================================
-- WLF Electrical Solution v2.5.9
--  * Hardware Catalogue: one database of controller-wise hardware
--    (MOT, NICE3000+ ... plus AVR 15-120 KVA), LOP / COP / Transom and
--    other components. Filled from the controller-wise QMS workbook.
--  * Raise Damage Demand takes item code / name / spec from the catalogue.
--    Damage Demand and Supplier Claim flows are unchanged.
--  * QMS: one record per lift (Lift ID is unique), saved before delivery.
--  * New permissions: "QMS / Edit saved lift records", "QMS / Delete saved
--    lift records", "Hardware Catalogue / Add, edit, delete, import".
-- Run in Supabase > SQL Editor after v2.5.8 (UPDATE_V258.sql). Safe to run
-- twice. Back up first. If an RLS warning appears, choose "Run without RLS".
-- =====================================================================
begin;

do $pre$ begin
  if to_regprocedure('wlf_private.rpc_before_v258(text,jsonb)') is null then
    raise exception 'STOP: apply UPDATE_V258.sql (v2.5.8) first. Nothing was changed.';
  end if;
end $pre$;

-- ---------------------------------------------------------------- permissions
do $c$ begin
  if to_regprocedure('wlf_private.catalog_before_v259()') is null then
    alter function wlf_private.catalog() rename to catalog_before_v259;
  end if;
end $c$;
create or replace function wlf_private.catalog() returns jsonb
language sql stable security definer set search_path='' as $$
  select wlf_private.catalog_before_v259() || jsonb_build_array(
    jsonb_build_object('key','qms:edit','label','QMS / Edit saved lift records','group','QMS'),
    jsonb_build_object('key','qms:delete','label','QMS / Delete saved lift records','group','QMS'),
    jsonb_build_object('key','catalogue:edit','label','Hardware Catalogue / Add, edit, delete, import','group','QMS'))
$$;

-- ---------------------------------------------------------------- catalogue tables
create table if not exists wlf_private.hw_catalogue(
  id uuid primary key default gen_random_uuid(),
  system text not null check (length(btrim(system)) between 1 and 60),
  model text not null check (length(btrim(model)) between 1 and 80),
  grp text not null default '' check (length(grp)<=80),
  hardware text not null default '' check (length(hardware)<=160),
  spec text not null default '' check (length(spec)<=240),
  item_code text not null default '' check (length(item_code)<=60),
  item_name text not null default '' check (length(item_name)<=240),
  brand text not null default '' check (length(brand)<=80),
  supplier text not null default '' check (length(supplier)<=80),
  value numeric(14,2),
  sort integer not null default 0,
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid,
  deleted_at timestamptz
);
create index if not exists hw_catalogue_model_idx on wlf_private.hw_catalogue(system,model,sort) where deleted_at is null;
alter table wlf_private.hw_catalogue enable row level security;
revoke all on wlf_private.hw_catalogue from public, anon, authenticated;

create table if not exists wlf_private.hw_suggest(
  keyword text primary key check (length(btrim(keyword)) between 1 and 60),
  groups text[] not null default '{}'
);
alter table wlf_private.hw_suggest enable row level security;
revoke all on wlf_private.hw_suggest from public, anon, authenticated;
insert into wlf_private.hw_suggest(keyword,groups) values
  ('drive',array['Drive','MOT Drive Internal Card','Braking','Circuit Breaker']),
  ('encoder',array['Control PCB']),
  ('pcb',array['Control PCB','MOT Drive Internal Card']),
  ('power',array['Power Supply','Transformer','Circuit Breaker','RCCB','UPS','ARD','Battery']),
  ('supply',array['Power Supply','Transformer','Circuit Breaker','RCCB']),
  ('brake',array['Braking','Contactor']),
  ('contactor',array['Contactor','Overload System']),
  ('overload',array['Overload System']),
  ('ups',array['UPS','ARD','Battery']),
  ('battery',array['UPS','ARD','Battery']),
  ('door',array['Control PCB']),
  ('communication',array['Control PCB']),
  ('electrical',array['Power Supply','Contactor','Circuit Breaker','RCCB','Transformer','Control PCB']),
  ('display',array['COP Display','COP Button','LOP','Transom Display']),
  ('avr',array['AVR'])
on conflict (keyword) do nothing;

